#pragma once

#include <AK/CircularQueue.h>
#include <AK/Stream.h>

namespace AK {

// FIXME: There are a lot of raw loops here, that's not necessary an issue but it
//        has to be verified that the optimizer is able to insert memcpy instead.
template<size_t Capacity>
class CircularDuplexStream : public AK::DuplexStream {
public:
    size_t write(ReadonlyBytes bytes) override
    {
        const auto nwritten = min(bytes.size(), Capacity - m_queue.size());

        for (size_t idx = 0; idx < nwritten; ++idx)
            m_queue.enqueue(bytes[idx]);

        m_total_written += nwritten;
        return nwritten;
    }

    bool write_or_error(ReadonlyBytes bytes) override
    {
        if (Capacity - m_queue.size() < bytes.size()) {
            set_recoverable_error();
            return false;
        }

        const auto nwritten = write(bytes);
        VERIFY(nwritten == bytes.size());
        return true;
    }

    size_t read(Bytes bytes) override
    {
        if (has_any_error())
            return 0;

        const auto nread = min(bytes.size(), m_queue.size());

        for (size_t idx = 0; idx < nread; ++idx)
            bytes[idx] = m_queue.dequeue();

        return nread;
    }

    size_t read(Bytes bytes, size_t seekback)
    {
        if (seekback > Capacity || seekback > m_total_written) {
            set_recoverable_error();
            return 0;
        }

        const auto nread = min(bytes.size(), seekback);

        for (size_t idx = 0; idx < nread; ++idx) {
            const auto index = (m_total_written - seekback + idx) % Capacity;
            bytes[idx] = m_queue.m_storage[index];
        }

        return nread;
    }

    bool read_or_error(Bytes bytes) override
    {
        if (m_queue.size() < bytes.size()) {
            set_recoverable_error();
            return false;
        }

        read(bytes);
        return true;
    }

    bool discard_or_error(size_t count) override
    {
        if (m_queue.size() < count) {
            set_recoverable_error();
            return false;
        }

        for (size_t idx = 0; idx < count; ++idx)
            m_queue.dequeue();

        return true;
    }

    bool unreliable_eof() const override { return eof(); }
    bool eof() const { return m_queue.size() == 0; }

    size_t remaining_contigous_space() const
    {
        return min(Capacity - m_queue.size(), m_queue.capacity() - (m_queue.head_index() + m_queue.size()) % Capacity);
    }

    Bytes reserve_contigous_space(size_t count)
    {
        VERIFY(count <= remaining_contigous_space());

        Bytes bytes { m_queue.m_storage + (m_queue.head_index() + m_queue.size()) % Capacity, count };

        m_queue.m_size += count;
        m_total_written += count;

        return bytes;
    }

private:
    CircularQueue<u8, Capacity> m_queue;
    size_t m_total_written { 0 };
};

}

using AK::CircularDuplexStream;

# A second test document

This file isn't really a snazzy demo of the markdown integration. It's more of just a means to have one-off coverage on some features as I develop them.

```

testWhileLoop();
testDoWhileLoop();

sumTest = sumNumbers1To100();
print("Sum of the numbers from 1 to 100:", sumTest);

print(ternaryTest('apple', 4));
print(ternaryTest('apple', 1));
print(ternaryTest('apple', 0));

print("5! = " + factorialRecursive(5));

testIncrement();
dictionaryTest();

jsonTest();
```

### Dictionary Test

```
dict = {
    "a": 1,
    "b": 2,
};

assert(dict["a"] == 1, "checking key 'a'");
assert(dict["b"] == 2, "checking key 'b'");

dict['c'] = 3;
assert(dict['c'] == 3, "checking key 'c'");

assert(dict.keys() + '' == '[a, b, c]', "checking keys");
assert(dict.values() + '' == '[1, 2, 3]', "checking values");

dict['b'] = 4;
assert(dict.keys() + '' == '[a, b, c]', "checking keys");
assert(dict.values() + '' == '[1, 4, 3]', "checking values");

dict['d'] = 5;
assert(dict.length == 4, "check length");
assert(dict.keys() + '' == '[a, b, c, d]', "checking keys");
assert(dict.values() + '' == '[1, 4, 3, 5]', "checking values");

dict.remove('a');
assert(dict.length == 3, "check length");
assert(dict.keys() + '' == '[d, b, c]', "checking keys");
assert(dict.values() + '' == '[5, 4, 3]', "checking values");

dict.remove('c');
assert(dict.length == 2, "check length");
assert(dict.keys() + '' == '[d, b]', "checking keys");
assert(dict.values() + '' == '[5, 4]', "checking values");

assert(dict.get('d') == 5, "getting a key that exists with .get()");
assert(dict.get('e') == null, "getting a key that doesn't exist with no fallback");
assert(dict.get('f', 'bananas') == 'bananas', "getting a key that doesn't exist with a fallback");

print("Dictionary tests passed");

```

### Test Increment

```
a = 10;
b = a++;
assert(a == 11, "a++");
assert(b == 10, "b = a++");
c = a--;
assert(a == 10, "a--");
assert(c == 11, "c = a--");
a += 1;
assert(a == 11, "a += 1");

a = 10;
b = ++a;
assert(a == 11, "++a");
assert(b == 11, "b = ++a");
c = --a;
assert(a == 10, "--a");
assert(c == 10, "c = --a");

a = [10];
b = a[0]++;
assert(a[0] == 11, "a[0]++");
assert(b == 10, "b = a[0]++");
c = a[0]--;
assert(a[0] == 10, "a[0]--");
assert(c == 11, "c = a[0]--");

a = [10];
b = ++a[0];
assert(a[0] == 11, "++a[0]");
assert(b == 11, "b = ++a[0]");
c = --a[0];
assert(a[0] == 10, "--a[0]");
assert(c == 10, "c = --a[0]");
a[0] += 1;
assert(a[0] == 11, "a[0] += 1");

a = DummyObject.init();
a.num = 10;
b = ++a.num;
assert(a.num == 11, "++a.num");
assert(b == 11, "b = ++a.num");
c = --a.num;
assert(a.num == 10, "--a.num");
assert(c == 10, "c = --a.num");

a.num += 1;
assert(a.num == 11, "a.num += 1");

a = { 'num': 10 };
b = ++a['num'];
assert(a['num'] == 11, "++a['num']");
assert(b == 11, "b = ++a['num']");
c = --a['num'];
assert(a['num'] == 10, "--a['num']");
assert(c == 10, "c = --a['num']");

a['num'] += 1;
assert(a['num'] == 11, "a['num'] += 1");

print("Increment tests passed");

```

### Factorial Recursive

- `n` - the value to calculate the factorial of

```
if n < 2 {
    return 1;
}
return factorialRecursive(n - 1) * n;
```

